import pytest


def accepted(cap: int, xs: list[int]) -> int:
    """Return how many elements of xs are accepted by a bounded queue.

    The queue holds at most ``cap`` items and nothing is removed from it.
    Each element of ``xs`` is put without blocking, in order. A put is
    accepted while the queue has room. The first put that finds the queue
    full stops the process, and the count of accepted puts is returned.
    A capacity ``cap <= 0`` means the queue has no room, so nothing is
    accepted. It does not mean unbounded.
    """
    count = 0
    for _ in xs:
        if count >= cap:
            break
        count += 1
    return count


def test_accepted_stops_when_full() -> None:
    assert accepted(2, [1, 2, 3]) == 2


def test_accepted_all_fit() -> None:
    assert accepted(5, [7, 8]) == 2


def test_accepted_empty_input() -> None:
    assert accepted(3, []) == 0


def test_accepted_zero_capacity() -> None:
    assert accepted(0, [1, 2]) == 0


def test_accepted_negative_capacity_is_not_unbounded() -> None:
    assert accepted(-1, [1, 2, 3]) == 0


def test_accepted_exact_fit() -> None:
    assert accepted(3, [1, 2, 3]) == 3
